commands.command:
cat > /etc/nginx/nginx.conf <<'ANTRIEB_NGINX_MAIN'
user nginx;
worker_processes auto;
error_log /var/log/nginx/error.log;
pid /run/nginx.pid;
include /usr/share/nginx/modules/*.conf;

events {
    worker_connections 1024;
}

http {
    log_format main '$remote_addr - $remote_user [$time_local] "$request" $status $body_bytes_sent';
    access_log /var/log/nginx/access.log main;
    sendfile on;
    tcp_nopush on;
    tcp_nodelay on;
    keepalive_timeout 65;
    types_hash_max_size 4096;
    include /etc/nginx/mime.types;
    default_type application/octet-stream;
    include /etc/nginx/conf.d/*.conf;
}
ANTRIEB_NGINX_MAIN
cat > /etc/nginx/conf.d/https-8443.conf <<'ANTRIEB_NGINX_TLS'
server {
    listen 8443 ssl;
    listen [::]:8443 ssl;
    server_name _;
    root /usr/share/nginx/html;

    ssl_certificate /etc/nginx/tls/current/cert.pem;
    ssl_certificate_key /etc/nginx/tls/current/key.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_session_cache shared:TLS:10m;
    ssl_session_timeout 10m;

    location = /healthz {
        default_type text/plain;
        return 200 'healthy\n';
    }
}
ANTRIEB_NGINX_TLS
cat > /usr/share/nginx/html/index.html <<'ANTRIEB_INDEX'
<!doctype html>
<html><head><title>node1 HTTPS</title></head><body><h1>Certificate rotation service</h1><p>node1 is healthy.</p></body></html>
ANTRIEB_INDEX
cat > /etc/systemd/system/rotate-https-certificate.service <<'ANTRIEB_ROTATE_SERVICE'
[Unit]
Description=Renew and gracefully deploy the node1 HTTPS certificate
Documentation=man:openssl-req(1)

[Service]
Type=oneshot
ExecStart=/usr/local/sbin/rotate-https-certificate
ANTRIEB_ROTATE_SERVICE
cat > /etc/systemd/system/rotate-https-certificate.timer <<'ANTRIEB_ROTATE_TIMER'
[Unit]
Description=Check the node1 HTTPS certificate twice daily

[Timer]
OnBootSec=5min
OnUnitActiveSec=12h
RandomizedDelaySec=15min
Persistent=true
Unit=rotate-https-certificate.service

[Install]
WantedBy=timers.target
ANTRIEB_ROTATE_TIMER
restorecon -RF /etc/nginx /usr/share/nginx/html /usr/local/sbin/rotate-https-certificate /etc/systemd/system/rotate-https-certificate.service /etc/systemd/system/rotate-https-certificate.timer
systemd-analyze verify /etc/systemd/system/rotate-https-certificate.service /etc/systemd/system/rotate-https-certificate.timer
ls -lZ /etc/nginx/nginx.conf /etc/nginx/conf.d/https-8443.conf /usr/share/nginx/html/index.html /etc/systemd/system/rotate-https-certificate.*
